<script setup>
import {computed,ref} from 'vue';
import FormDialog from './FormDialog.vue';
import {api} from '../services/accounting.js';
import {errorText} from '../locales/accounting.js';
import {payrollErrors,payrollAccountLabels} from '../locales/payroll.js';
import {reportMoney as money} from '../services/report-format.js';
const props=defineProps({slip:Object}),emit=defineEmits(['close','saved']);
const options=ref(props.slip.proposal.options),selected=ref({...props.slip.proposal.accounts}),plan=ref(null),busy=ref(false),error=ref(''),requestId=crypto.randomUUID();
const needed=computed(()=>{const t=props.slip.calculation.totals;return Object.keys(payrollAccountLabels).filter(key=>key==='wages'||key==='social_payable'&&(t.employee_ss!=='0.00'||t.employer_ss!=='0.00')||key==='social_expense'&&t.employer_ss!=='0.00'||key==='net'&&t.net!=='0.00'||key==='withholding'&&t.irpf!=='0.00'||key==='advance'&&t.advance!=='0.00'||key==='other'&&t.other_deductions!=='0.00');});
async function prepare(){busy.value=true;error.value='';try{await api('/payroll/accounts/prepare',{method:'POST',body:{}});const row=await api('/payroll/slips/'+props.slip.id);options.value=row.proposal.options;selected.value={...row.proposal.accounts};plan.value=null;}catch(cause){error.value=payrollErrors[cause.code]||errorText(cause);}finally{busy.value=false;}}
async function calculate(){busy.value=true;error.value='';try{plan.value=await api('/payroll/slips/'+props.slip.id+'/post-preview',{method:'POST',body:{version:props.slip.version,accounts:selected.value}});selected.value={...plan.value.accounts};}catch(cause){error.value=payrollErrors[cause.code]||errorText(cause);}finally{busy.value=false;}}
async function post(){if(!plan.value?.ready)return;busy.value=true;error.value='';try{emit('saved',await api('/payroll/slips/'+props.slip.id+'/post',{method:'POST',body:{version:props.slip.version,request_id:requestId,accounts:plan.value.accounts,proposal_hash:plan.value.hash}}));}catch(cause){error.value=payrollErrors[cause.code]||errorText(cause);}finally{busy.value=false;}}
</script>
<template><FormDialog class="payroll-dialog" title="Contabilizar nómina" :busy="busy" @close="emit('close')"><div class="payroll-form"><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p>Revisa las subcuentas y el asiento antes de contabilizar. El líquido quedará pendiente de pago en 465.</p><button class="button" :disabled="busy" @click="prepare">Crear cuentas de nóminas que falten</button><fieldset :disabled="busy"><div class="payroll-fields"><label v-for="key in needed" :key="key">{{ payrollAccountLabels[key] }}<select v-model="selected[key]" :aria-label="payrollAccountLabels[key]" @change="plan=null"><option :value="null">Seleccionar subcuenta</option><option v-for="row in options[key]" :key="row.id" :value="row.id">{{ row.code }} · {{ row.description }}</option></select></label></div></fieldset><button class="button" :disabled="busy" @click="calculate">Revisar asiento de nómina</button><template v-if="plan"><p v-if="plan.missing.length" class="notice">Selecciona las subcuentas pendientes.</p><div class="table-wrap"><table><thead><tr><th>Cuenta</th><th>Concepto</th><th class="amount">Debe</th><th class="amount">Haber</th></tr></thead><tbody><tr v-for="(line,index) in plan.lines" :key="index"><td>{{ line.code }}</td><td>{{ line.description }}</td><td class="amount">{{ money(line.debit) }}</td><td class="amount">{{ money(line.credit) }}</td></tr></tbody><tfoot><tr><th colspan="2">Total</th><td class="amount">{{ money(plan.totals.debit) }}</td><td class="amount">{{ money(plan.totals.credit) }}</td></tr></tfoot></table></div></template><div class="dialog-actions"><button class="button" :disabled="busy" @click="emit('close')">Cancelar</button><button class="button primary" :disabled="busy||!plan?.ready" @click="post">Confirmar y contabilizar nómina</button></div></div></FormDialog></template>
